package com.github.istin.dmtools.ai.utils;

import junit.framework.TestCase;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.List;

public class AIResponseParserTest extends TestCase {

    public void testParseBooleanWithExplanation_TrueWithExplanation() {
        AIResponseParser.BooleanWithExplanation result = AIResponseParser.parseBooleanWithExplanation("true, because it validates the same flow");
        assertTrue(result.value);
        assertEquals("because it validates the same flow", result.explanation);
    }

    public void testParseBooleanWithExplanation_TrueWithoutComma() {
        AIResponseParser.BooleanWithExplanation result = AIResponseParser.parseBooleanWithExplanation("true");
        assertTrue(result.value);
        assertNull(result.explanation);
    }

    public void testParseBooleanWithExplanation_FalseNoExplanation() {
        AIResponseParser.BooleanWithExplanation result = AIResponseParser.parseBooleanWithExplanation("false");
        assertFalse(result.value);
        assertNull(result.explanation);
    }

    public void testParseBooleanWithExplanation_FalseIgnoresTrailingText() {
        AIResponseParser.BooleanWithExplanation result = AIResponseParser.parseBooleanWithExplanation("false, not related");
        assertFalse(result.value);
        assertNull(result.explanation);
    }

    public void testParseBooleanWithExplanation_TrueDeprecationReason() {
        AIResponseParser.BooleanWithExplanation result = AIResponseParser.parseBooleanWithExplanation(
            "true, This test case needs to be deprecated once this story is delivered.");
        assertTrue(result.value);
        assertEquals("This test case needs to be deprecated once this story is delivered.", result.explanation);
    }

    public void testParseBooleanWithExplanation_ReturnsFalseOnInvalidInput() {
        AIResponseParser.BooleanWithExplanation result = AIResponseParser.parseBooleanWithExplanation("maybe");
        assertFalse(result.value);
        assertNull(result.explanation);

        AIResponseParser.BooleanWithExplanation emptyResult = AIResponseParser.parseBooleanWithExplanation("   ");
        assertFalse(emptyResult.value);
        assertNull(emptyResult.explanation);

        AIResponseParser.BooleanWithExplanation nullResult = AIResponseParser.parseBooleanWithExplanation(null);
        assertFalse(nullResult.value);
        assertNull(nullResult.explanation);
    }

    public void testParseBooleanWithExplanation_MarkdownFormatting() {
        assertFalse(AIResponseParser.parseBooleanWithExplanation("**false**").value);
        assertTrue(AIResponseParser.parseBooleanWithExplanation("__true__").value);
        assertTrue(AIResponseParser.parseBooleanWithExplanation("_true_").value);
        assertFalse(AIResponseParser.parseBooleanWithExplanation("_false_").value);
        assertTrue(AIResponseParser.parseBooleanResponse("__true__"));
        assertFalse(AIResponseParser.parseBooleanResponse("__false__"));
        assertFalse(AIResponseParser.parseBooleanWithExplanation("*false*").value);
        assertFalse(AIResponseParser.parseBooleanWithExplanation("__false__").value);
        assertFalse(AIResponseParser.parseBooleanWithExplanation("`false`").value);
        assertFalse(AIResponseParser.parseBooleanWithExplanation("\"false\"").value);
        assertFalse(AIResponseParser.parseBooleanWithExplanation("false.").value);
        assertFalse(AIResponseParser.parseBooleanWithExplanation("```\nfalse\n```").value);

        AIResponseParser.BooleanWithExplanation boldTrue = AIResponseParser.parseBooleanWithExplanation(
                "**true**, because it validates the login flow");
        assertTrue(boldTrue.value);
        assertEquals("because it validates the login flow", boldTrue.explanation);

        AIResponseParser.BooleanWithExplanation codeTrue = AIResponseParser.parseBooleanWithExplanation(
                "`true`, covers the same authentication scenario");
        assertTrue(codeTrue.value);
        assertEquals("covers the same authentication scenario", codeTrue.explanation);

        AIResponseParser.BooleanWithExplanation multilineTrue = AIResponseParser.parseBooleanWithExplanation(
                "**True**\nBecause the story modifies the same endpoint.");
        assertTrue(multilineTrue.value);
        assertEquals("Because the story modifies the same endpoint.", multilineTrue.explanation);

        AIResponseParser.BooleanWithExplanation fencedTrue = AIResponseParser.parseBooleanWithExplanation(
                "```text\ntrue, related to password reset\n```");
        assertTrue(fencedTrue.value);
        assertEquals("related to password reset", fencedTrue.explanation);
    }

    public void testParseBooleanResponse() {
        assertTrue(AIResponseParser.parseBooleanResponse("... true ..."));
        assertFalse(AIResponseParser.parseBooleanResponse("... false ..."));
        assertTrue(AIResponseParser.parseBooleanResponse("**true**"));
        assertFalse(AIResponseParser.parseBooleanResponse("**false**"));
        assertTrue(AIResponseParser.parseBooleanResponse("`true`"));
        assertFalse(AIResponseParser.parseBooleanResponse("`false`"));
        assertFalse(AIResponseParser.parseBooleanResponse("... invalid ..."));
        assertFalse(AIResponseParser.parseBooleanResponse(""));
        assertFalse(AIResponseParser.parseBooleanResponse(null));
    }

    public void testParseCodeResponseVariations() {
        // Test without language identifier
        String response1 = "```\nsome code\n```";
        assertEquals("some code", AIResponseParser.parseCodeResponse(response1));

        // Test single line
        String response2 = "```javascript\nsome code```";
        assertEquals("some code", AIResponseParser.parseCodeResponse(response2));

        // Test without code markers
        String response3 = "some code";
        assertEquals("some code", AIResponseParser.parseCodeResponse(response3));

        // Test empty response

    // Test empty response
    try {
        AIResponseParser.parseCodeResponse("");
        fail("Should throw IllegalArgumentException");
    } catch (IllegalArgumentException e) {
        // Expected
    }

    // Test null response
    try {
        AIResponseParser.parseCodeResponse(null);
        fail("Should throw IllegalArgumentException");
    } catch (IllegalArgumentException e) {
        // Expected
    }
}

public void testParseResponseAsJSONArray() {
    try {
        String response = "... [\"item1\", \"item2\"] ...";
        JSONArray jsonArray = AIResponseParser.parseResponseAsJSONArray(response);
        assertEquals(2, jsonArray.length());
        assertEquals("item1", jsonArray.getString(0));
        assertEquals("item2", jsonArray.getString(1));

        try {
            AIResponseParser.parseResponseAsJSONArray("invalid response");
            fail("Expected JSONException for invalid JSON array");
        } catch (JSONException e) {
            // Expected exception
        }
    } catch (Exception e) {
        fail("Exception should not be thrown: " + e.getMessage());
    }
}

public void testParseResponseAsJSONObject() {
    try {
        String response = "... {\"key\": \"value\"} ...";
        JSONObject jsonObject = AIResponseParser.parseResponseAsJSONObject(response);
        assertEquals("value", jsonObject.getString("key"));

        try {
            AIResponseParser.parseResponseAsJSONObject("invalid response");
            fail("Expected JSONException for invalid JSON object");
        } catch (JSONException e) {
            // Expected exception
        }
    } catch (Exception e) {
        fail("Exception should not be thrown: " + e.getMessage());
    }
}

public void testParseCodeExamples() {
    try {
        String response = "Example 1:\n```\nCode block 1\n```\nExample 2:\n```\nCode block 2\n```";
        List<String> codeExamples = AIResponseParser.parseCodeExamples(response, "```", "```");
        assertEquals(2, codeExamples.size());
        assertEquals("Code block 1", codeExamples.get(0));
        assertEquals("Code block 2", codeExamples.get(1));

        // Test with no delimiters
        try {
            AIResponseParser.parseCodeExamples("No code blocks here", "```", "```");
            fail("Expected IllegalArgumentException for missing code blocks");
        } catch (IllegalArgumentException e) {
            // Expected exception
        }

        // Test with empty response
        try {
            AIResponseParser.parseCodeExamples("", "```", "```");
            fail("Expected IllegalArgumentException for empty response");
        } catch (IllegalArgumentException e) {
            // Expected exception
        }

    } catch (Exception e) {
        fail("Exception should not be thrown during valid code extraction: " + e.getMessage());
    }
}

