import 'package:dmtools/dmtools.dart';
import 'package:test/test.dart';

/// Scratch probe (deleted after run): fixed-code parity vs Java
/// AIResponseParser.cleanExplanation semantics.
void main() {
  test('probe: fixed explanation cleanup vs Java parity', () {
    final cases = <String, String>{
      'true, status is tracked': 'status is tracked',
      'true, this is serious': 'this is serious',
      'true so it works': 'so it works',
      'true - tests pass': 'tests pass',
      'true, since status works': 'since status works',
      '**true**, * because *': 'because',
    };
    cases.forEach((input, javaExpected) {
      final parsed = AIResponseParser.parseBooleanWithExplanation(input);
      final actual = parsed.explanation;
      // ignore: avoid_print
      print('input=[$input] -> dart=[$actual] java=[$javaExpected]');
      expect(actual, javaExpected, reason: 'input: $input');
    });
    // fallback path (token pattern): explanation cleanup must still work
    final fb = AIResponseParser.parseBooleanWithExplanation(
      'Answer: **true**, status matches',
    );
    // ignore: avoid_print
    print('fallback -> dart=[${fb.explanation}] java=[status matches]');
    expect(fb.value, isTrue);
    expect(fb.explanation, 'status matches');
  });
}

